template:
@php
    $variant = in_array($variant, ['cards', 'hero', 'gallery'], true) ? $variant : 'cards';
    $count = max(1, min(12, (int) ($slides ?: 6)));
    // Pictures drawn on the spot: the showcase loads nothing from anywhere but the site.
    $picture = static function (int $i, int $width, int $height): string {
        $hue = (int) (($i * 47 + 200) % 360);
        $svg = "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 {$width} {$height}'>"
            ."<rect width='100%' height='100%' fill='hsl({$hue} 45% 42%)'/>"
            ."<circle cx='".($width * 0.72)."' cy='".($height * 0.38)."' r='".($height * 0.22)."' fill='hsl({$hue} 60% 70%)'/>"
            ."<path d='M0 {$height} L".($width * 0.35).' '.($height * 0.45).' L'.($width * 0.6)." {$height} Z' fill='hsl({$hue} 40% 28%)'/></svg>";

        return 'data:image/svg+xml,'.rawurlencode($svg);
    };
    // The words are the block's fields, so that the Russian and the Polish pages read in theirs.
    $words = array_values(array_filter(array_map(trim(...), explode("\n", (string) $titles)), static fn (string $word): bool => $word !== ''));
    $word = static fn (int $i): string => $words === [] ? (string) $i : $words[($i - 1) % count($words)];
    $say = static fn (?string $line, int $i): string => strtr((string) $line, [':count' => $count, ':n' => $i, ':word' => $word($i)]);
@endphp
<section class="b-showcase-slider b-showcase-slider--{{ $width === 'narrow' ? 'narrow' : 'full' }}" data-wx-block="showcase-slider">
    @if ($heading)
        <h2 class="b-showcase-slider__heading">{{ $heading }}</h2>
    @endif
    @if ($note)
        <p class="b-showcase-slider__note">{{ $note }}</p>
    @endif
    <div class="b-showcase-slider__frame">
        <x-webx-slider :variant="$variant" :label="$heading ?: null">
            @for ($i = 1; $i <= $count; $i++)
                @switch($variant)
                    @case('hero')
                        <x-webx-slide>
                            <div class="b-showcase-slider__hero">
                                <img class="b-showcase-slider__hero-image" src="{{ $picture($i, 1200, 500) }}" width="1200" height="500" alt="">
                                <div class="b-showcase-slider__hero-text">
                                    <p class="b-showcase-slider__hero-title">{{ $say($hero ?: ':word', $i) }}</p>
                                    <a class="b-showcase-slider__hero-link" href="#slide-{{ $i }}">{{ $say($slide, $i) }}</a>
                                </div>
                            </div>
                        </x-webx-slide>
                        @break
                    @case('gallery')
                        <x-webx-slide>
                            <img class="b-showcase-slider__photo" src="{{ $picture($i, 1200, 800) }}" width="1200" height="800" alt="{{ $say($photo, $i) }}">
                        </x-webx-slide>
                        @break
                    @default
                        <x-webx-slide>
                            <article class="b-showcase-slider__card">
                                <img class="b-showcase-slider__card-image" src="{{ $picture($i, 600, 360) }}" width="600" height="360" alt="">
                                <h3 class="b-showcase-slider__card-title">{{ $word($i) }}</h3>
                                <p class="b-showcase-slider__card-text">{{ $say($card, $i) }}{{ $i % 3 === 0 && $longer ? ' '.$longer : '' }}</p>
                                <a class="b-showcase-slider__card-link" href="#card-{{ $i }}">{{ strtr((string) $more, [':word' => mb_strtolower($word($i))]) }}</a>
                            </article>
                        </x-webx-slide>
                @endswitch
            @endfor
        </x-webx-slider>
    </div>
</section>

styles:
.b-showcase-slider {
    max-width: var(--site-container-width);
    margin: 0 auto;
    padding: var(--site-space-6) var(--site-gutter);
}

.b-showcase-slider__heading {
    margin: 0 0 var(--site-space-2);
}

.b-showcase-slider__note {
    margin: 0 0 var(--site-space-4);
    color: var(--site-color-text-muted);
}

.b-showcase-slider--narrow .b-showcase-slider__frame {
    max-width: 20rem;
    padding: var(--site-space-3);
    border: 1px dashed var(--site-color-border);
}

.b-showcase-slider__card {
    display: flex;
    flex-direction: column;
    gap: var(--site-space-2);
    height: 100%;
    box-sizing: border-box;
    padding: var(--site-space-3);
    border: 1px solid var(--site-color-border);
    border-radius: var(--site-radius-md);
    background: var(--site-color-surface);
}

.b-showcase-slider__card-image,
.b-showcase-slider__photo,
.b-showcase-slider__hero-image {
    display: block;
    width: 100%;
    height: auto;
    border-radius: var(--site-radius-sm);
}

.b-showcase-slider__card-title {
    margin: 0;
    font-size: var(--site-font-size-4);
}

.b-showcase-slider__card-text {
    margin: 0;
    flex: 1;
}

.b-showcase-slider__hero {
    position: relative;
}

.b-showcase-slider__hero-text {
    position: absolute;
    inset: auto 0 0 0;
    padding: var(--site-space-4);
    background: var(--site-color-surface);
    opacity: 0.92;
}

.b-showcase-slider__hero-title {
    margin: 0;
    font-size: var(--site-font-size-5);
    font-weight: 700;
}
